WITH profiles(id,created_at) AS(VALUES ('00000000-0000-4000-8000-000000000001'::uuid,'2026-11-20T10:05:00Z'::timestamptz),('00000000-0000-4000-8000-000000000002'::uuid,'2026-11-20T10:05:00Z'::timestamptz),('00000000-0000-4000-8000-000000000003'::uuid,'2026-11-20T10:05:00Z'::timestamptz),('00000000-0000-4000-8000-000000000005'::uuid,'2026-11-20T10:05:00Z'::timestamptz),('00000000-0000-4000-8000-000000000006'::uuid,'2026-11-20T10:05:00Z'::timestamptz),('00000000-0000-4000-8000-000000000004'::uuid,'2026-10-01T00:00:00Z'::timestamptz),('00000000-0000-4000-8000-000000000007'::uuid,'2026-11-21T00:01:00Z'::timestamptz),('00000000-0000-4000-8000-000000000008'::uuid,'2026-11-21T10:05:00Z'::timestamptz),('00000000-0000-4000-8000-000000000009'::uuid,'2026-11-20T23:58:00Z'::timestamptz),('00000000-0000-4000-8000-000000000010'::uuid,'2026-11-21T00:01:00Z'::timestamptz)), events(id,session_id,name,path,created_at,user_id,metadata) AS(VALUES ('00000000-0000-4000-8000-000000000100'::uuid,'a','landing_session_started','/how-much-do-youtube-shorts-pay','2026-11-20T10:00:00Z'::timestamptz,NULL::uuid,'{"is_bot":false,"referrer_host":"bing.com"}'::jsonb),('00000000-0000-4000-8000-000000000101'::uuid,'a','landing_session_started','/ignored-duplicate','2026-11-20T10:01:00Z'::timestamptz,NULL::uuid,'{"is_bot":false,"referrer_host":"chatgpt.com"}'::jsonb),('00000000-0000-4000-8000-000000000102'::uuid,'a','signup','/signup','2026-11-20T10:05:00Z'::timestamptz,'00000000-0000-4000-8000-000000000001'::uuid,'{}'::jsonb),('00000000-0000-4000-8000-000000000103'::uuid,'b','landing_session_started','/how-much-do-instagram-reels-pay','2026-11-21T11:00:00Z'::timestamptz,'00000000-0000-4000-8000-000000000001'::uuid,'{"is_bot":false,"referrer_host":"chatgpt.com"}'::jsonb),('00000000-0000-4000-8000-000000000104'::uuid,'c','landing_session_started','/how-much-do-instagram-reels-pay','2026-11-20T11:00:00Z'::timestamptz,NULL::uuid,'{"is_bot":false,"referrer_host":"chatgpt.com"}'::jsonb),('00000000-0000-4000-8000-000000000105'::uuid,'c','signup','/signup','2026-11-20T11:05:00Z'::timestamptz,'00000000-0000-4000-8000-000000000002'::uuid,'{}'::jsonb),('00000000-0000-4000-8000-000000000106'::uuid,'staff','landing_session_started','/how-much-do-youtube-shorts-pay','2026-11-20T12:00:00Z'::timestamptz,'00000000-0000-4000-8000-000000000003'::uuid,'{"is_bot":false,"referrer_host":"bing.com"}'::jsonb),('00000000-0000-4000-8000-000000000107'::uuid,'old','landing_session_started','/how-much-do-youtube-shorts-pay','2026-11-20T12:10:00Z'::timestamptz,'00000000-0000-4000-8000-000000000004'::uuid,'{"is_bot":false,"referrer_host":"bing.com"}'::jsonb),('00000000-0000-4000-8000-000000000108'::uuid,'bot','landing_session_started','/how-much-do-youtube-shorts-pay','2026-11-20T12:20:00Z'::timestamptz,'00000000-0000-4000-8000-000000000005'::uuid,'{"is_bot":true,"referrer_host":"bing.com"}'::jsonb),('00000000-0000-4000-8000-000000000109'::uuid,'ambiguous','landing_session_started','/how-much-do-instagram-reels-pay','2026-11-20T13:00:00Z'::timestamptz,'00000000-0000-4000-8000-000000000002'::uuid,'{"is_bot":false,"referrer_host":"chatgpt.com"}'::jsonb),('00000000-0000-4000-8000-000000000110'::uuid,'ambiguous','session','/studio','2026-11-20T13:01:00Z'::timestamptz,'00000000-0000-4000-8000-000000000006'::uuid,'{}'::jsonb),('00000000-0000-4000-8000-000000000111'::uuid,'missing','landing_session_started','/how-much-do-instagram-reels-pay','2026-11-20T13:10:00Z'::timestamptz,NULL::uuid,'{"is_bot":false}'::jsonb),('00000000-0000-4000-8000-000000000112'::uuid,'a','payment_success','/api/stripe/webhook','2026-11-20T14:00:00Z'::timestamptz,'00000000-0000-4000-8000-000000000001'::uuid,'{"source":"stripe_webhook","stripe_livemode":true,"stripe_payment_status":"paid","amount_total":100}'::jsonb),('00000000-0000-4000-8000-000000000113'::uuid,'a','payment_success','/api/stripe/webhook','2026-11-20T14:00:00Z'::timestamptz,'00000000-0000-4000-8000-000000000001'::uuid,'{"source":"stripe_webhook","stripe_livemode":true,"stripe_payment_status":"paid","amount_total":100}'::jsonb),('00000000-0000-4000-8000-000000000114'::uuid,'c','payment_success','/checkout/success','2026-11-20T14:20:00Z'::timestamptz,'00000000-0000-4000-8000-000000000002'::uuid,'{"source":"client","stripe_livemode":false,"stripe_payment_status":"unpaid","amount_total":100}'::jsonb),('00000000-0000-4000-8000-000000000701'::uuid,'boundary','landing_session_started','/how-much-do-youtube-shorts-pay','2026-11-20T23:59:00Z'::timestamptz,NULL::uuid,'{"is_bot":false,"referrer_host":"bing.com"}'::jsonb),('00000000-0000-4000-8000-000000000702'::uuid,'boundary','signup','/signup','2026-11-21T00:01:00Z'::timestamptz,'00000000-0000-4000-8000-000000000007'::uuid,'{}'::jsonb),('00000000-0000-4000-8000-000000000703'::uuid,'boundary','payment_success','/api/stripe/webhook','2026-11-21T02:00:00Z'::timestamptz,'00000000-0000-4000-8000-000000000007'::uuid,'{"source":"stripe_webhook","stripe_livemode":true,"stripe_payment_status":"paid","amount_total":100}'::jsonb),('00000000-0000-4000-8000-000000000801'::uuid,'after','landing_session_started','/how-much-do-youtube-shorts-pay','2026-11-21T10:00:00Z'::timestamptz,NULL::uuid,'{"is_bot":false,"referrer_host":"bing.com"}'::jsonb),('00000000-0000-4000-8000-000000000802'::uuid,'after','signup','/signup','2026-11-21T10:05:00Z'::timestamptz,'00000000-0000-4000-8000-000000000008'::uuid,'{}'::jsonb),('00000000-0000-4000-8000-000000000803'::uuid,'after','payment_success','/api/stripe/webhook','2026-11-22T10:00:00Z'::timestamptz,'00000000-0000-4000-8000-000000000008'::uuid,'{"source":"stripe_webhook","stripe_livemode":true,"stripe_payment_status":"paid","amount_total":100}'::jsonb),('00000000-0000-4000-8000-000000000901'::uuid,'late-link','landing_session_started','/how-much-do-youtube-shorts-pay','2026-11-20T23:59:00Z'::timestamptz,NULL::uuid,'{"is_bot":false,"referrer_host":"bing.com"}'::jsonb),('00000000-0000-4000-8000-000000000902'::uuid,'late-link','auth','/studio','2026-11-21T00:01:00Z'::timestamptz,'00000000-0000-4000-8000-000000000009'::uuid,'{}'::jsonb),('00000000-0000-4000-8000-000000001001'::uuid,'late-profile','landing_session_started','/how-much-do-youtube-shorts-pay','2026-11-20T23:59:00Z'::timestamptz,'00000000-0000-4000-8000-000000000010'::uuid,'{"is_bot":false,"referrer_host":"bing.com"}'::jsonb),('00000000-0000-4000-8000-000000002001'::uuid,'c','payment_success','/api/stripe/webhook','2026-11-21T01:00:00Z'::timestamptz,'00000000-0000-4000-8000-000000000002'::uuid,'{"source":"stripe_webhook","stripe_livemode":true,"stripe_payment_status":"paid","amount_total":100}'::jsonb)), videos(user_id,created_at,status,quality_mode) AS(VALUES ('00000000-0000-4000-8000-000000000001'::uuid,'2026-11-20T15:00:00Z'::timestamptz,'completed','cinematic_ai'),('00000000-0000-4000-8000-000000000001'::uuid,'2026-11-20T16:00:00Z'::timestamptz,'completed','cinematic_ai'),('00000000-0000-4000-8000-000000000002'::uuid,'2026-11-20T16:00:00Z'::timestamptz,'completed','clip'),('00000000-0000-4000-8000-000000000002'::uuid,'2026-11-21T01:00:00Z'::timestamptz,'completed','cinematic_ai'),('00000000-0000-4000-8000-000000000007'::uuid,'2026-11-21T01:00:00Z'::timestamptz,'completed','cinematic_ai'),('00000000-0000-4000-8000-000000000008'::uuid,'2026-11-22T11:00:00Z'::timestamptz,'completed','cinematic_ai')), params AS (
 SELECT '2026-11-22T00:00:00Z'::timestamptz observed_cut,'2026-11-21T00:00:00Z'::timestamptz live_from
), observed AS (SELECT least(observed_cut,statement_timestamp()) cut,live_from FROM params),
windows AS (
 SELECT 'antes'::text phase,live_from-interval '14 days' phase_start,least(cut,live_from) phase_cut FROM observed WHERE live_from IS NOT NULL AND cut>live_from-interval '14 days'
 UNION ALL SELECT 'depois',live_from,least(cut,live_from+interval '14 days') FROM observed WHERE live_from IS NOT NULL AND cut>live_from
 UNION ALL SELECT 'baseline_sem_exposicao',cut-interval '14 days',cut FROM observed WHERE live_from IS NULL
), internal_profiles AS(SELECT '00000000-0000-4000-8000-000000000003'::uuid id),
raw AS (
 SELECT DISTINCT ON(w.phase,e.session_id) w.phase,w.phase_start,w.phase_cut,e.id,e.session_id,e.created_at,split_part(e.path,'?',1) path,e.metadata
 FROM windows w JOIN events e ON e.created_at>=w.phase_start AND e.created_at<w.phase_cut
 WHERE e.name='landing_session_started' AND e.session_id IS NOT NULL
 ORDER BY w.phase,e.session_id,e.created_at,e.id
), linked AS (
 SELECT r.*,u.ids,u.n,u.internal FROM raw r CROSS JOIN LATERAL(
 SELECT array_agg(DISTINCT e.user_id) FILTER(WHERE e.user_id IS NOT NULL) ids,count(DISTINCT e.user_id) n,bool_or(i.id IS NOT NULL) internal
 FROM events e LEFT JOIN internal_profiles i ON i.id=e.user_id
 WHERE e.session_id=r.session_id AND e.created_at>=r.created_at AND e.created_at<r.phase_cut
 )u WHERE r.metadata->>'is_bot'='false' AND NOT coalesce(u.internal,false)
), first_account AS (
 SELECT DISTINCT ON(l.phase,p.id) l.phase,p.id uid,l.session_id,p.created_at signed_at,l.phase_start,l.phase_cut
 FROM linked l JOIN profiles p ON p.id=ANY(l.ids)
 WHERE l.n=1 AND p.created_at>=l.phase_start AND p.created_at<l.phase_cut AND p.id NOT IN(SELECT id FROM internal_profiles)
 ORDER BY l.phase,p.id,l.created_at,l.id
), origins AS (SELECT l.*,CASE
 WHEN lower(coalesce(metadata->>'referrer_host','')) IN ('chatgpt','chatgpt.com','www.chatgpt.com') OR coalesce(metadata->>'utm_source','') ILIKE '%chatgpt%' THEN 'chatgpt_explicito'
 WHEN lower(coalesce(metadata->>'referrer_host','')) IN ('bing','bing.com','www.bing.com') OR lower(coalesce(metadata->>'utm_source',''))='bing' THEN CASE WHEN lower(coalesce(metadata->>'utm_medium',''))='cpc' THEN 'bing_pago' ELSE 'bing_explicito' END
 WHEN lower(coalesce(metadata->>'referrer_host','')) IN ('google.com','www.google.com','google') OR lower(coalesce(metadata->>'utm_source',''))='google' THEN 'google'
 WHEN lower(coalesce(metadata->>'referrer_host','')) IN ('duckduckgo.com','www.duckduckgo.com') OR lower(coalesce(metadata->>'utm_source',''))='duckduckgo' THEN 'duckduckgo'
 WHEN lower(coalesce(metadata->>'referrer_host','')) IN ('youtube.com','www.youtube.com','m.youtube.com','youtu.be') OR lower(coalesce(metadata->>'utm_source',''))='youtube' THEN 'youtube'
 WHEN lower(coalesce(metadata->>'utm_source',''))='affiliate' THEN 'afiliado_rotulado'
 WHEN lower(coalesce(metadata->>'utm_source','')) IN ('instagram','ig') THEN 'instagram'
 WHEN nullif(metadata->>'referrer_host','') IS NULL AND nullif(metadata->>'utm_source','') IS NULL THEN 'origem_nao_gravada'
 ELSE 'outra_origem_gravada' END origin FROM linked l),
film AS (
 SELECT a.phase,a.uid,min(v.created_at) first_film_history_at
 FROM first_account a JOIN videos v ON v.user_id=a.uid
 WHERE v.status='completed' AND v.quality_mode IN ('cinematic_ai','cinematic_hollywood','cinematic_kling','cinematic_veo','cinematic_h3','cinematic_omni')
 AND v.created_at>=a.signed_at AND v.created_at<a.phase_cut GROUP BY a.phase,a.uid
), paid AS (
 SELECT DISTINCT a.phase,e.user_id uid FROM events e JOIN first_account a ON a.uid=e.user_id
 WHERE e.name='payment_success' AND (
 (e.path='/api/stripe/webhook' AND e.metadata->>'source'='stripe_webhook' AND e.metadata->>'stripe_livemode'='true' AND e.metadata->>'stripe_payment_status'='paid')
 OR (e.path='/api/dodo/webhook' AND e.metadata->>'source'='dodo_webhook' AND e.metadata->>'dodo_mode'='live')
 ) AND e.metadata->>'amount_total' ~ '^[0-9]+$' AND (e.metadata->>'amount_total')::numeric>0
 AND e.created_at>=a.signed_at AND e.created_at<a.phase_cut
), groups AS (
 SELECT l.phase,l.origin,l.path,count(*) sessions,count(DISTINCT a.uid) accounts,count(DISTINCT f.uid) first_film_delivered,count(DISTINCT p.uid) paid_people,count(*) FILTER(WHERE l.n>1) ambiguous_sessions
 FROM origins l LEFT JOIN first_account a ON a.phase=l.phase AND a.session_id=l.session_id
 LEFT JOIN film f ON f.phase=a.phase AND f.uid=a.uid LEFT JOIN paid p ON p.phase=a.phase AND p.uid=a.uid
 WHERE l.path IN ('/how-much-do-youtube-shorts-pay','/how-much-do-instagram-reels-pay') GROUP BY l.phase,l.origin,l.path
), coverage AS (
 SELECT w.phase,count(DISTINCT p.id) all_new_external_accounts,count(DISTINCT a.uid) accounts_with_eligible_session,
 count(DISTINCT p.id) FILTER(WHERE a.uid IS NULL) accounts_without_eligible_session
 FROM windows w JOIN profiles p ON p.created_at>=w.phase_start AND p.created_at<w.phase_cut
 LEFT JOIN first_account a ON a.phase=w.phase AND a.uid=p.id
 WHERE p.id NOT IN(SELECT id FROM internal_profiles) GROUP BY w.phase
)
SELECT jsonb_build_object('criterion','conversion inside each phase; independent phase cut for identity, signup, film history and paid event',
'observed_cut',(SELECT cut FROM observed),'live_from',(SELECT live_from FROM observed),
'after_not_observed',(SELECT live_from IS NULL OR cut<=live_from FROM observed),
'after_complete',(SELECT coalesce(cut>=live_from+interval '14 days',false) FROM observed),
'windows',(SELECT jsonb_agg(to_jsonb(w) ORDER BY phase) FROM windows w),
'coverage',(SELECT jsonb_agg(to_jsonb(c) ORDER BY phase) FROM coverage c),
'rows',(SELECT jsonb_agg(to_jsonb(g) ORDER BY phase,accounts DESC,sessions DESC,path) FROM groups g)) measurement;
